<?php

declare(strict_types=1);

namespace App\Calls\Scripts;

use App\Contracts\CallSender;
use App\Data\ProfileDraftData;
use App\Data\ProfileLanguageData;
use App\Data\ProfileRunData;
use App\Support\CallKey;

/**
 * The signed calls of Scripts, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class ScriptCalls
{
    public function __construct(private CallSender $sender) {}

    /**
     * @param  array<string, mixed>  $commands
     */
    public function checkProfileScript(
        string $profile,
        string $source,
        array $commands = [],
    ): ProfileDraftData {
        return $this->sender->send(CheckProfileScriptCall::from([
            'profile' => $profile,
            'source' => $source,
            'commands' => $commands,
        ]));
    }

    public function readProfileLanguage(
    ): ProfileLanguageData {
        return $this->sender->send(ReadProfileLanguageCall::from([
        ]));
    }

    /**
     * @param  array<string, mixed>  $commands
     */
    public function saveProfileDraft(
        CallKey $requestKey,
        string $profile,
        int $expectedRevision,
        string $source,
        array $commands = [],
    ): ProfileDraftData {
        return $this->sender->send(SaveProfileDraftCall::from([
            'requestKey' => $requestKey,
            'profile' => $profile,
            'expectedRevision' => $expectedRevision,
            'source' => $source,
            'commands' => $commands,
        ]));
    }

    public function showProfileDraft(
        string $profile,
    ): ProfileDraftData {
        return $this->sender->send(ShowProfileDraftCall::from([
            'profile' => $profile,
        ]));
    }

    public function showProfileRun(
        string $id,
    ): ProfileRunData {
        return $this->sender->send(ShowProfileRunCall::from([
            'id' => $id,
        ]));
    }
}
